#include "descriptions.h"

#include "async_log.h"
#include "descriptions_key.h" // generated by tools/seal-descriptions

#include <windows.h>

extern "C" IMAGE_DOS_HEADER __ImageBase; // this plugin's own module, which carries the sealed words

namespace D2RAccess::Descriptions {

SealedText::Texts OpenBundled(const D2RL::PluginContext* context) {
	const auto module = reinterpret_cast<HMODULE>(&__ImageBase);
	const HRSRC info = FindResourceW(module, L"DESCRIPTIONS", reinterpret_cast<LPCWSTR>(RT_RCDATA));
	const HGLOBAL handle = info ? LoadResource(module, info) : nullptr;
	const auto* bytes = handle ? static_cast<const uint8_t*>(LockResource(handle)) : nullptr;
	if (!bytes) {
		AsyncLog::Warn(context, "[descriptions] none: the sealed words are missing from the plugin");
		return {};
	}
	const auto opened = SealedText::Open({bytes, SizeofResource(module, info)}, Generated::DescriptionsKey);
	if (!opened) {
		AsyncLog::Warn(context, "[descriptions] none: the sealed words were altered");
		return {};
	}
	return SealedText::Unpack(*opened);
}

}
